-- Hit lists (2026-11-24, per Chad): call lists built from three spreadsheets
-- Chad uploaded 11/24, with every number checked against live sales instead of
-- the spreadsheets' June numbers. Plan: claude/hit-lists-plan.md. Sources:
-- claude/hit-lists-source-1-sf-off-prem.md, -2-rep-plan.md, -3-off-prem-ryan.md.
--
--   matagrano-sf     Distributors → Matagrano → Today's priorities → "Hit list":
--                    "SF Off Prem 1.xlsx" (SF indie re-engagement list) + the whole
--                    "Santa Clara County" tab of "Off Prem Ryan 1.xlsx".
--   valley-wide-cv   Distributors → Valley Wide → "Hit list": the Valley Wide
--                    accounts on the "Central Valley" tab of "Off Prem Ryan 1.xlsx".
--   mussetter-cv     Distributors → Mussetter → "Hit list": the Mussetter accounts
--                    on that same tab.
--   rep-plan-top100  Sales Dashboard → "Top 100 rep plan": "rep plan 1.xlsx" (Top 100
--                    Off-Premise Attack Plan). Bill → Lance, Saccani → Mussetter (Chad).
--
-- Left out (Chad): Molsberry's (Eagle — no Eagle page). Healthy Spirits use their
-- real accounts (3948391 Valencia, 3922983 Cortland); Bel Air #528 = 2777125;
-- Rainbow Grocery listed once. Turned-off accounts (e.g. Epicurean Trader) drop
-- out automatically, like every other list.
--
-- What's live (worked out on every open, so it updates after each LilyPad sync):
-- last order + who from, CEs last 12 months, CEs since the list's data date, last
-- check-in, contacts. What comes from the spreadsheet: priority, group, rep, play,
-- why, peak / current items, and the sheet's status + last buy (for "was").
--
--   hit_lists                 the 4 lists (title, page, data date)
--   hit_list_accounts         the accounts on each list
--   hit_list(list)            one list, live numbers
--   hit_list_account(outlet)  account pop-up: all-time purchases + all check-ins
-- Access: a distributor's list = anyone who can see that distributor's page; the
-- rep plan = Sales Dashboard people.
-- Run this in Supabase's SQL Editor BEFORE pushing the code. Safe to run more than once.

create table if not exists public.hit_lists (
  list_key text primary key,
  title text not null,
  distributor text,            -- whose page it's on; null = Sales Dashboard
  data_through date not null,  -- the spreadsheet's numbers went up to here
  source text
);
alter table public.hit_lists enable row level security;
drop policy if exists "hit_lists_read" on public.hit_lists;
create policy "hit_lists_read" on public.hit_lists for select using (
  case when distributor is null then public.has_section(auth.uid(), 'sales_dashboard') else public.sales_can_see(array[distributor]) end
);
grant select on public.hit_lists to authenticated;
grant select, insert, update, delete on public.hit_lists to service_role;
comment on table public.hit_lists is
  'Hit lists (call lists of accounts to go after) built from spreadsheets Chad uploaded 11/24/2026: matagrano-sf (SF + Santa Clara-area off-premise re-engagement, Matagrano page), valley-wide-cv and mussetter-cv (Central Valley re-engagement, Valley Wide / Mussetter pages), rep-plan-top100 (Top 100 off-premise rep plan, Sales Dashboard). data_through = the date the spreadsheet''s own numbers went up to.';

create table if not exists public.hit_list_accounts (
  list_key text not null references public.hit_lists(list_key) on delete cascade,
  outlet_id text not null references public.sales_accounts(outlet_id) on delete cascade,
  sort integer not null,
  section text,         -- group on the spreadsheet (New door / Recently lapsed / Lapsed / Dormant)
  priority text,        -- ★ / ★★ / ★★★ from the spreadsheet
  rep text,             -- rep plan: Lance / Steve / Ryan / Eric
  list_name text not null,
  list_distributor text,
  list_city text,
  play text,            -- rep plan: recommended play
  why text,             -- the spreadsheet's reason to go after it
  peak_skus integer,    -- rep plan: most items carried at once (spreadsheet)
  current_skus integer, -- rep plan: items carried then (spreadsheet)
  sheet_status text,
  sheet_last_buy text,
  primary key (list_key, outlet_id)
);
alter table public.hit_list_accounts enable row level security;
drop policy if exists "hit_list_accounts_read" on public.hit_list_accounts;
create policy "hit_list_accounts_read" on public.hit_list_accounts for select using (
  exists (select 1 from public.hit_lists l where l.list_key = hit_list_accounts.list_key
    and case when l.distributor is null then public.has_section(auth.uid(), 'sales_dashboard') else public.sales_can_see(array[l.distributor]) end)
);
grant select on public.hit_list_accounts to authenticated;
grant select, insert, update, delete on public.hit_list_accounts to service_role;
comment on table public.hit_list_accounts is
  'The accounts on each hit list (see hit_lists): priority stars, group, rep (rep plan), recommended play, why to go after it, and the spreadsheet''s status / last buy / peak and current items. Live numbers come from sales_account_sales via hit_list(list). Use for "who is on the SF hit list / Lance''s rep plan accounts / why is X on the list".';

insert into public.hit_lists (list_key, title, distributor, data_through, source) values
  ('matagrano-sf', 'SF Off-Prem hit list', 'Matagrano', '2026-06-30', 'SF Off Prem 1.xlsx + Off Prem Ryan 1.xlsx (Santa Clara County tab), June 2026'),
  ('valley-wide-cv', 'Central Valley hit list', 'Valley Wide', '2026-06-30', 'Off Prem Ryan 1.xlsx (Central Valley tab), June 2026'),
  ('mussetter-cv', 'Central Valley hit list', 'Mussetter', '2026-06-30', 'Off Prem Ryan 1.xlsx (Central Valley tab), June 2026'),
  ('rep-plan-top100', 'Top 100 rep plan', null, '2026-04-30', 'rep plan 1.xlsx (Top 100 Off-Premise Attack Plan, VIP data Jan 2023 – Apr 2026)')
on conflict (list_key) do update set title = excluded.title, distributor = excluded.distributor,
  data_through = excluded.data_through, source = excluded.source;

insert into public.hit_list_accounts (list_key, outlet_id, sort, section, priority, rep, list_name, list_distributor,
