  sheet_status = excluded.sheet_status, sheet_last_buy = excluded.sheet_last_buy;

-- Can this person see this list?
create or replace function public.hit_list_can_see(p_list text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.hit_lists l where l.list_key = p_list
    and case when l.distributor is null then public.has_section(auth.uid(), 'sales_dashboard')
             else public.sales_can_see(array[l.distributor]) end);
$$;
revoke all on function public.hit_list_can_see(text) from public, anon;
grant execute on function public.hit_list_can_see(text) to authenticated;
comment on function public.hit_list_can_see(text) is '[hidden] Access check for a hit list.';

-- ---------------------------------------------------------------------------
-- One list with live numbers. Turned-off accounts are left out.
-- ---------------------------------------------------------------------------
create or replace function public.hit_list(p_list text)
returns json
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  a date;
  l public.hit_lists;
  result json;
begin
  if not public.hit_list_can_see(p_list) then
    raise exception 'You don''t have access to this list.';
  end if;
  select * into l from public.hit_lists where list_key = p_list;
  select m.as_of into a from public.sales_data_meta m where m.id = 1;
  with t as (
    select b.* from public.hit_list_accounts b
    where b.list_key = p_list
      and not exists (select 1 from public.sales_account_off o where o.outlet_id = b.outlet_id)
  ),
  s as (
    select r.outlet_id, coalesce(r.distributor, '') as dist, coalesce(r.last_buy_date, r.month) as d, r.month, r.ce
    from public.sales_account_sales r
    where r.outlet_id in (select outlet_id from t)
      and not exists (select 1 from public.sales_product_hidden h where h.product = r.product)
  ),
  g as (
    select s.outlet_id,
      max(s.d) as last_buy,
      (array_agg(s.dist order by s.d desc))[1] as last_dist,
      round(coalesce(sum(s.ce) filter (where s.month >= (date_trunc('month', a) - interval '11 months')::date), 0), 1) as ce_12mo,
      round(coalesce(sum(s.ce) filter (where s.month > l.data_through), 0), 1) as ce_since,
      max(s.d) filter (where s.d > l.data_through) as bought_since
    from s group by s.outlet_id
  )
  select json_build_object(
    'as_of', a,
    'list', json_build_object('key', l.list_key, 'title', l.title, 'distributor', l.distributor, 'data_through', l.data_through, 'source', l.source),
    'accounts', (select coalesce(json_agg(x order by x.sort), '[]'::json) from (
      select t.outlet_id, t.sort, t.section, t.priority, t.rep, t.list_name, t.list_distributor, t.list_city,
        t.play, t.why, t.peak_skus, t.current_skus, t.sheet_status, t.sheet_last_buy,
        ac.name, ac.city, ac.address, ac.phone, ac.premise, ac.distributor,
        g.last_buy, g.last_dist, coalesce(g.ce_12mo, 0) as ce_12mo, coalesce(g.ce_since, 0) as ce_since, g.bought_since,
        (select k.checkin_date from public.sales_account_checkins k where k.outlet_id = t.outlet_id order by k.checkin_date desc limit 1) as last_checkin,
        (select k.rep from public.sales_account_checkins k where k.outlet_id = t.outlet_id order by k.checkin_date desc limit 1) as last_checkin_rep,
        (select count(*) from public.sales_account_contacts c where c.outlet_id = t.outlet_id) as contacts
      from t
      join public.sales_accounts ac on ac.outlet_id = t.outlet_id
      left join g on g.outlet_id = t.outlet_id) x)
  ) into result;
  return result;
end;
$$;
revoke all on function public.hit_list(text) from public, anon;
grant execute on function public.hit_list(text) to authenticated;
comment on function public.hit_list(text) is
  $c$[needs:sales_dashboard] One hit list (matagrano-sf, valley-wide-cv, mussetter-cv, rep-plan-top100) with live numbers per account: last order + who from, CEs last 12 months, CEs and last order since the spreadsheet's data date (bought_since = won back / bought again), last check-in and who, contacts — plus the spreadsheet's priority, group, rep, play, why, peak / current items. Distributor lists are also open to that distributor's page.$c$;

-- ---------------------------------------------------------------------------
-- Account pop-up: ALL-TIME purchases (with who sold it), ALL check-ins, contacts.
-- Open to anyone who can see a hit list the account is on (some SF-list accounts
-- are Chrissa / Geyser accounts), plus the usual account access.
-- ---------------------------------------------------------------------------
create or replace function public.hit_list_account(p_outlet text)
returns json
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_dist text;
  result json;
begin
  select a.distributor into v_dist from public.sales_accounts a where a.outlet_id = p_outlet;
  if not found or not (
      exists (select 1 from public.hit_list_accounts b where b.outlet_id = p_outlet and public.hit_list_can_see(b.list_key))
      or public.has_section(auth.uid(), 'accounts')
      or (v_dist is not null and public.sales_can_see(array[v_dist]))) then
    raise exception 'You don''t have access to this account.';
  end if;
  select json_build_object(
    'account', (select json_build_object('outlet_id', a.outlet_id, 'name', a.name, 'address', a.address, 'city', a.city,
        'zip', a.zip, 'phone', a.phone, 'distributor', a.distributor, 'premise', a.premise, 'last_buy', a.last_buy_date,
        'first_buy', a.first_buy_date, 'ce_12mo', a.ce_12mo, 'lifetime_ce', a.lifetime_ce)
      from public.sales_accounts a where a.outlet_id = p_outlet),
    'as_of', (select m.as_of from public.sales_data_meta m where m.id = 1),
    'all_time', true,
    'sales', (select coalesce(json_agg(x order by x.month desc, x.ce desc), '[]'::json) from (
        select s.month, s.product, coalesce(s.size, '') as size, coalesce(s.distributor, '') as dist,
          round(sum(s.ce), 1) as ce, max(s.last_buy_date) as last_buy
        from public.sales_account_sales s
        where s.outlet_id = p_outlet
        group by 1, 2, 3, 4) x),
    'checkins', (select coalesce(json_agg(x order by x.checkin_date desc), '[]'::json) from (
        select k.checkin_date, k.rep, k.activity, k.notes, k.brands, k.contact
        from public.sales_account_checkins k where k.outlet_id = p_outlet) x),
    'contacts', (select coalesce(json_agg(x order by x.name nulls last), '[]'::json) from (
        select c.name, c.title, c.phone, c.mobile, c.email, c.notes
        from public.sales_account_contacts c where c.outlet_id = p_outlet) x)
  ) into result;
  return result;
end;
$$;
revoke all on function public.hit_list_account(text) from public, anon;
grant execute on function public.hit_list_account(text) to authenticated;
comment on function public.hit_list_account(text) is
  $c$[needs:sales_dashboard] One account on a hit list: address, phone, last order, every month of what it bought all time (and which distributor sold it), every check-in, contacts.$c$;
